//! The bytes, checked against the Go P-Chain.
//!
//! Two implementations of a chain agree about a transaction only if they agree
//! about its bytes, because the bytes are what a signature covers and what an
//! id is the hash of. So the claim "this is the same wire" has to be checked
//! against the other implementation rather than against itself.
//!
//! Every vector below was emitted by the Go P-Chain
//! (`luxfi/node/vms/platformvm`) building the same value with the same fields,
//! and is pasted here verbatim. Each case asserts both directions: the bytes
//! this port writes are byte-identical to Go's, and Go's bytes read back into
//! the same value.
//!
//! Regenerating them is a Go program that calls `txs.New*Tx` and
//! `block.New*Block` and prints hex; it is quoted in LLM.md so a future change
//! to either side can be checked the same way.

use lux_platformvm::block;
use lux_platformvm::components::Utxo;
use lux_platformvm::components::{Credential, Input, Output, Owners, UtxoId};
use lux_platformvm::genesis::{Allocation, Genesis};
use lux_platformvm::ids::{NodeId, ShortId};
use lux_platformvm::security::{Admission, Manager, Mode};
use lux_platformvm::sign;
use lux_platformvm::signer::Signer;
use lux_platformvm::txs::{Envelope, Kind, NetworkValidator, PChainOwner, Tx, Unsigned, Validator};

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[i * 2..i * 2 + 2], 16).unwrap())
        .collect()
}

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

fn id(b: u8) -> [u8; 32] {
    [b; 32]
}

fn out(asset: u8, amount: u64, owner: u8) -> Output {
    Output {
        asset: id(asset),
        stake_lock: 0,
        amount,
        owners: Owners {
            locktime: 0,
            threshold: 1,
            addrs: vec![ShortId([owner; 20])],
        },
    }
}

fn input(tx: u8, index: u32, amount: u64) -> Input {
    Input {
        utxo: UtxoId {
            tx_id: id(tx),
            output_index: index,
        },
        asset: id(9),
        stake_lock: 0,
        amount,
        sig_indices: vec![0],
    }
}

fn base() -> Envelope {
    Envelope {
        network_id: 1,
        blockchain_id: id(3),
        outs: vec![out(9, 100, 1)],
        ins: vec![input(1, 0, 200)],
        memo: Vec::new(),
    }
}

fn owners(b: u8) -> Owners {
    Owners {
        locktime: 0,
        threshold: 1,
        addrs: vec![ShortId([b; 20])],
    }
}

fn validator() -> Validator {
    Validator {
        node_id: NodeId([5; 20]),
        start: 1000,
        end: 2000,
        weight: 50,
    }
}

fn stake() -> Vec<Output> {
    vec![out(9, 50, 2)]
}

/// Assert this port writes exactly what Go wrote, and reads exactly what Go
/// meant.
fn same_wire(name: &str, tx: Unsigned, go_hex: &str) {
    let want = unhex(go_hex);
    let got = tx.to_bytes();
    assert_eq!(hex(&got), hex(&want), "{name}: bytes differ from Go's");
    let back = Unsigned::parse(&want).unwrap_or_else(|e| panic!("{name}: {e}"));
    assert_eq!(back, tx, "{name}: Go's bytes do not read back as the value");
    // And an id is the hash of those bytes, so both sides name it the same.
    assert_eq!(Tx::new(back, Vec::new()).id(), Tx::new(tx, Vec::new()).id());
}

#[test]
fn a_base_transaction_is_byte_identical_to_go() {
    same_wire(
        "base",
        Unsigned::Base(base()),
        "",
    );
}
