#[test]
fn the_block_kinds_are_byte_identical_to_go() {
    let cases: &[(&str, block::Block, &str)] = &[
        (
            "standard",
            block::Block::standard(id(1), 5, 1000, Vec::new()),
            "5a4150000200000010000000510000000401010101010101010101010101010101010101010101010101010101010101010500000000000000e80300000000000000000000000000000000000000000000",
        ),
        ("commit", block::Block::commit(id(1), 5, 1000), "5a4150000200000010000000410000000201010101010101010101010101010101010101010101010101010101010101010500000000000000e803000000000000"),
        ("abort", block::Block::abort(id(1), 5, 1000), "5a4150000200000010000000410000000101010101010101010101010101010101010101010101010101010101010101010500000000000000e803000000000000"),
    ];
    for (name, blk, go_hex) in cases {
        let want = unhex(go_hex);
        assert_eq!(
            hex(blk.bytes()),
            hex(&want),
            "{name}: bytes differ from Go's"
        );
        // A block's name is the hash of exactly those bytes, so Go and this
        // port call the same block by the same name.
        let back = block::Block::parse(&want).unwrap();
        assert_eq!(back.id(), blk.id(), "{name}: different ids for one block");
        assert_eq!(back.kind(), blk.kind());
        assert_eq!(back.parent(), id(1));
        assert_eq!(back.height(), 5);
        assert_eq!(back.timestamp(), 1000);
    }
}

#[test]
fn gos_transaction_bytes_are_a_prefix_of_the_signed_form() {
    // The property the whole signing scheme rests on, checked against real Go
    // bytes rather than against bytes this port made up.
    let unsigned = unhex("");
    let tx = Tx::parse(&unsigned).unwrap();
    assert_eq!(tx.unsigned_bytes(), &unsigned[..]);
    assert_eq!(tx.unsigned.kind(), Kind::Base);
}

#[test]
fn a_signer_that_go_would_write_reads_back() {
    // Go stores a signer inline: one tag byte, then the key, then the proof.
    // A permissionless validator is the one transaction that carries one, so
    // the round trip is checked through a whole transaction rather than in
    // isolation.
    let sk = blst::min_pk::SecretKey::key_gen(&[4u8; 32], &[]).unwrap();
    let tx = Unsigned::AddPermissionlessValidator {
        base: base(),
        validator: validator(),
        chain: lux_platformvm::ids::PRIMARY_NETWORK_ID,
        signer: Signer::prove(&sk),
        stake: stake(),
        validator_rewards_owner: owners(3),
        delegator_rewards_owner: owners(4),
        delegation_shares: 20_000,
    };
    let bytes = tx.to_bytes();
    assert_eq!(Unsigned::parse(&bytes).unwrap(), tx);
}

