/// Credentials, including an empty one in the middle — the case where the
/// shared signature array's ranges are the only thing keeping the entries
/// apart.
#[test]
fn a_signed_transaction_is_byte_identical_to_go() {
    let want = unhex("");
    let creds = vec![
        Credential {
            sigs: vec![[1u8; 65], [2u8; 65]],
        },
        Credential { sigs: vec![] },
        Credential {
            sigs: vec![[3u8; 65]],
        },
    ];
    let tx = Tx::new(Unsigned::Base(base()), creds.clone());
    assert_eq!(hex(tx.bytes()), hex(&want), "signed bytes differ from Go's");

    let back = Tx::parse(&want).unwrap();
    assert_eq!(back.creds, creds);
    assert_eq!(back.id(), tx.id());
    // The unsigned prefix Go signed is the one this port would sign.
    assert_eq!(back.sighash(), tx.sighash());
}

#[test]
fn a_proposal_block_is_byte_identical_to_go() {
    let want = unhex("5a41500002000000100000008a0000000301010101010101010101010101010101010101010101010101010101010101010500000000000000e8030000000000000000000000000000000000000000000008000000310000005a415000020000001000000031000000020707070707070707070707070707070707070707070707070707070707070707");
    let proposal = Tx::new(
        Unsigned::RewardValidator {
            staker_tx_id: id(7),
        },
        Vec::new(),
    );
    let blk = block::Block::proposal(id(1), 5, 1000, proposal.clone());
    assert_eq!(
        hex(blk.bytes()),
        hex(&want),
        "proposal bytes differ from Go's"
    );

    let back = block::Block::parse(&want).unwrap();
    assert_eq!(back.id(), blk.id());
    assert_eq!(back.proposal_tx().unwrap().id(), proposal.id());
    assert!(back.decision_txs().is_empty());
}

#[test]
fn a_standard_block_carrying_a_transaction_is_byte_identical_to_go() {
    let want = unhex("");
    let tx = Tx::new(
        Unsigned::Base(base()),
        vec![
            Credential {
                sigs: vec![[1u8; 65], [2u8; 65]],
            },
            Credential { sigs: vec![] },
            Credential {
                sigs: vec![[3u8; 65]],
            },
        ],
    );
    let blk = block::Block::standard(id(1), 5, 1000, vec![tx.clone()]);
    assert_eq!(
        hex(blk.bytes()),
        hex(&want),
        "standard bytes differ from Go's"
    );

    let back = block::Block::parse(&want).unwrap();
    assert_eq!(back.id(), blk.id());
    assert_eq!(back.decision_txs().len(), 1);
    assert_eq!(back.decision_txs()[0].id(), tx.id());
}

/// The permissionless validator the `add_permissionless_validator` vector
/// carries, reused as the one genesis admits.
fn permissionless_validator() -> Unsigned {
    Unsigned::AddPermissionlessValidator {
        base: base(),
        validator: validator(),
        chain: [0; 32],
        signer: Signer::ProofOfPossession {
            public_key: [11; 48],
            proof: [12; 96],
        },
        stake: stake(),
        validator_rewards_owner: owners(3),
        delegator_rewards_owner: owners(4),
        delegation_shares: 20_000,
    }
}

/// The chain the `create_chain` vector makes, reused as the one genesis makes.
fn create_chain() -> Unsigned {
    Unsigned::CreateChain {
        base: base(),
        chain: id(6),
        vm_id: id(8),
        name: "a chain".to_string(),
        fx_ids: vec![id(1), id(2)],
        genesis: b"genesis bytes".to_vec(),
        chain_auth: vec![0, 2],
    }
}

/// The two genesis validators the network vectors carry, in node-id order.
fn genesis_set() -> Vec<NetworkValidator> {
    vec![
        NetworkValidator {
            node_id: vec![5u8; 20],
            weight: 100,
            balance: 900,
            signer: Signer::ProofOfPossession {
                public_key: [11u8; 48],
                proof: [12u8; 96],
            },
            remaining_balance_owner: PChainOwner {
                threshold: 1,
                addresses: vec![ShortId([1; 20])],
            },
            deactivation_owner: PChainOwner {
                threshold: 2,
                addresses: vec![ShortId([2; 20]), ShortId([3; 20])],
            },
        },
        NetworkValidator {
            node_id: vec![6u8; 20],
            weight: 200,
            balance: 800,
            signer: Signer::ProofOfPossession {
                public_key: [13u8; 48],
                proof: [14u8; 96],
            },
            remaining_balance_owner: PChainOwner {
                threshold: 1,
                addresses: vec![ShortId([4; 20])],
            },
            deactivation_owner: PChainOwner {
                threshold: 0,
                addresses: Vec::new(),
            },
        },
    ]
}

