/// The envelope an unspent output travels in, and the second envelope a lock
/// puts around it.
#[test]
fn an_unspent_output_is_byte_identical_to_go() {
    let plain = Utxo {
        id: UtxoId {
            tx_id: [0; 32],
            output_index: 0,
        },
        output: Output {
            asset: id(9),
            stake_lock: 0,
            amount: 100,
            owners: owners(1),
        },
    };
    assert_eq!(hex(&plain.wire_bytes()), "");
    assert_eq!(Utxo::parse_wire(&unhex("")).unwrap(), plain);

    let locked = Utxo {
        id: UtxoId {
            tx_id: [0; 32],
            output_index: 1,
        },
        output: Output {
            asset: id(9),
            stake_lock: 5000,
            amount: 250,
            owners: owners(1),
        },
    };
    assert_eq!(hex(&locked.wire_bytes()), "");
    assert_eq!(Utxo::parse_wire(&unhex("")).unwrap(), locked);
}

/// The whole first state of a network, byte for byte.
#[test]
fn a_genesis_is_byte_identical_to_go() {
    let allocation = |index: u32, amount: u64, stake_lock: u64| Allocation {
        utxo: Utxo {
            id: UtxoId {
                tx_id: [0; 32],
                output_index: index,
            },
            output: Output {
                asset: id(9),
                stake_lock,
                amount,
                owners: owners(1),
            },
        },
        message: b"hello".to_vec(),
    };
    let g = Genesis {
        utxos: vec![allocation(0, 100, 0), allocation(1, 250, 5000)],
        validators: vec![Tx::new(permissionless_validator(), Vec::new())],
        chains: vec![Tx::new(create_chain(), Vec::new())],
        timestamp: 1000,
        initial_supply: 360_000_000_000_000,
        message: "let there be light".to_string(),
    };
    let want = unhex("");
    assert_eq!(
        hex(&g.to_bytes()),
        hex(&want),
        "genesis bytes differ from Go's"
    );

    let back = Genesis::parse(&want).expect("Go's genesis reads back");
    assert_eq!(back, g);
    // The transactions genesis carries keep the names they were published
    // under — that is the whole reason they are stored as their own bytes.
    assert_eq!(back.validators[0].id(), g.validators[0].id());
    assert_eq!(back.chains[0].id(), g.chains[0].id());
}

/// The address a key spends under, and the address a signature names, both as
/// Go computes them.
///
/// This is the one thing the two implementations must agree about before any
/// spend can be checked: given a key, the same address; given a signature over
/// a hash, the same signer. A different hash chain or a different recovery
/// convention would let each side accept spends the other refuses.
#[test]
fn a_signature_names_the_address_go_names() {
    let sighash: [u8; 32] = [7; 32];
    let go_signature = unhex("111f20b9521ba1924ecfb91595426246b152cc1187e83f798cbd61f95f2c4cb107da8d209539506429d1ecd4033b2c207b89267f7dd8674421737193cd84f1dc00");
    let mut sig = [0u8; 65];
    sig.copy_from_slice(&go_signature);

    let recovered = sign::recover(&sighash, &sig).expect("Go's signature recovers");
    assert_eq!(
        hex(&recovered.0),
        "fc7250a211deddc70ee5a2738de5f07817351cef"
    );
}
